package com.magraoxx.eichattv;

import android.content.Context;
import android.content.Intent;
import android.net.Uri;
import android.util.Base64;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.RSAPublicKeySpec;
import java.math.BigInteger;
import java.util.*;

public final class ChatGptAuth {
 public interface Callback { void onSuccess(String message); void onError(String message); }
 private static final String AUTH="https://auth.openai.com/api/accounts/authorize", TOKEN="https://auth.openai.com/api/accounts/oauth/token", JWKS="https://auth.openai.com/.well-known/jwks.json", RESOURCE="https://api.openai.com/v1", SCOPES="openid profile email offline_access resource.invoke chatgpt.tokens.use.direct", PREFS="ei_chat_auth", HOST="host_id", AGENT="Ei Chat";
 private final Context context; private final SecureSecretStore secure;
 public ChatGptAuth(Context c){context=c.getApplicationContext();secure=new SecureSecretStore(c);}
 public boolean isConnected(){JSONObject p=profile();return p!=null&&p.optString("client_id").startsWith("oaiapp_")&&p.optString("scope").contains("chatgpt.tokens.use.direct");}
 public String accountLabel(){JSONObject p=profile();if(p==null)return "Não conectado";String e=p.optString("email","");return e.isEmpty()?"ChatGPT conectado":e;}

 public void signIn(Callback cb){new Thread(()->{ServerSocket server=null;try{
   server=openLoopback();server.setSoTimeout(10*60*1000);int port=server.getLocalPort();String redirect="http://127.0.0.1:"+port+"/auth/callback";
   String state=random(32),nonce=random(32),verifier=random(64),challenge=b64url(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII))),host=hostId();
   JSONObject old=profile();String requested=old==null?"dynamic_agent_client":old.optString("client_id","dynamic_agent_client");
   Uri.Builder u=Uri.parse(AUTH).buildUpon().appendQueryParameter("client_id",requested).appendQueryParameter("redirect_uri",redirect).appendQueryParameter("response_type","code").appendQueryParameter("scope",SCOPES).appendQueryParameter("resource",RESOURCE).appendQueryParameter("state",state).appendQueryParameter("nonce",nonce).appendQueryParameter("code_challenge_method","S256").appendQueryParameter("code_challenge",challenge).appendQueryParameter("ext_agent_host_id",host);
   if("dynamic_agent_client".equals(requested))u.appendQueryParameter("agent_name_hint",AGENT);else if(old!=null){String id=old.optString("id_token","");if(!id.isEmpty())u.appendQueryParameter("id_token_hint",id);String e=old.optString("email","");if(!e.isEmpty())u.appendQueryParameter("login_hint",e);}
   Intent i=new Intent(Intent.ACTION_VIEW,u.build());i.addCategory(Intent.CATEGORY_BROWSABLE);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);context.startActivity(i);
   Map<String,String> q=waitForCallback(server,state);
   if(q.containsKey("error"))throw new Exception("Autorização não concluída: "+q.get("error"));
   String code=q.get("code");if(code==null||code.isEmpty())throw new Exception("O ChatGPT não retornou o código de autorização.");
   String issued=q.get("client_id"),client=requested;
   if("dynamic_agent_client".equals(requested)){if(issued==null||!issued.startsWith("oaiapp_"))throw new Exception("Registro incompleto: client_id não retornado.");client=issued;}else if(issued!=null&&!issued.isEmpty()&&!issued.equals(requested))throw new Exception("O client_id retornado não corresponde à conta salva.");
   JSONObject t=tokenExchange("authorization_code",client,code,verifier,redirect,null);JSONObject identity=verifyIdToken(t.getString("id_token"),client,nonce);String scope=t.optString("scope",q.get("scope")==null?"":q.get("scope"));if(!scope.contains("chatgpt.tokens.use.direct"))throw new Exception("O uso do plano ChatGPT não foi autorizado.");
   if(old!=null&&!"dynamic_agent_client".equals(requested)){String previous=old.optString("subject","");if(!previous.isEmpty()&&!previous.equals(identity.optString("sub")))throw new Exception("A conta retornada é diferente da conta salva.");}
   JSONObject p=new JSONObject();p.put("client_id",client);p.put("host_id",host);p.put("subject",identity.getString("sub"));p.put("email",identity.optString("email",""));p.put("id_token",t.getString("id_token"));p.put("access_token",t.getString("access_token"));p.put("refresh_token",t.optString("refresh_token",""));p.put("scope",scope);p.put("expires_at",System.currentTimeMillis()+t.optLong("expires_in",3600)*1000L);saveProfile(p);cb.onSuccess("ChatGPT conectado"+(p.optString("email").isEmpty()?".":": "+p.optString("email")));
  }catch(Throwable x){cb.onError("Não consegui conectar ao ChatGPT: "+safe(x));}finally{if(server!=null)try{server.close();}catch(Exception ignored){}}},"ei-chat-auth").start();}

 private ServerSocket openLoopback() throws Exception {InetAddress loop=InetAddress.getByName("127.0.0.1");try{return new ServerSocket(1455,8,loop);}catch(BindException busy){return new ServerSocket(0,8,loop);}}
 private Map<String,String> waitForCallback(ServerSocket server,String expectedState)throws Exception{long end=System.currentTimeMillis()+10*60*1000;while(System.currentTimeMillis()<end){Socket s=server.accept();try{BufferedReader r=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));String req=r.readLine();Map<String,String> q=parseRequest(req);boolean callback=req!=null&&req.contains("/auth/callback");if(callback){String html="<!doctype html><html><head><meta name='viewport' content='width=device-width'></head><body style='font-family:sans-serif;text-align:center;padding:40px;background:#111;color:#fff'><h2>Ei Chat</h2><p>Autorização recebida. Você já pode voltar ao aplicativo.</p></body></html>";respond(s,html);if(!expectedState.equals(q.get("state")))throw new Exception("O retorno do login não pôde ser validado.");return q;}respond(s,"OK");}finally{try{s.close();}catch(Exception ignored){}}}throw new SocketTimeoutException("Tempo de autorização esgotado.");}
 private static void respond(Socket s,String html)throws Exception{byte[] b=html.getBytes(StandardCharsets.UTF_8);OutputStream o=s.getOutputStream();o.write(("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nCache-Control: no-store\r\nContent-Length: "+b.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));o.write(b);o.flush();}

 public synchronized String accessToken()throws Exception{JSONObject p=profile();if(p==null)throw new Exception("Conecte sua conta ChatGPT primeiro.");if(System.currentTimeMillis()<p.optLong("expires_at",0)-120000)return p.getString("access_token");String refresh=p.optString("refresh_token","");if(refresh.isEmpty())throw new Exception("Sua sessão expirou. Conecte o ChatGPT novamente.");JSONObject t=tokenExchange("refresh_token",p.getString("client_id"),null,null,null,refresh);p.put("access_token",t.getString("access_token"));if(!t.optString("refresh_token","").isEmpty())p.put("refresh_token",t.getString("refresh_token"));if(!t.optString("id_token","").isEmpty())p.put("id_token",t.getString("id_token"));if(!t.optString("scope","").isEmpty())p.put("scope",t.getString("scope"));p.put("expires_at",System.currentTimeMillis()+t.optLong("expires_in",3600)*1000L);saveProfile(p);return p.getString("access_token");}
 public void signOut(){secure.clear();}
 private JSONObject tokenExchange(String grant,String client,String code,String verifier,String redirect,String refresh)throws Exception{StringBuilder f=new StringBuilder();add(f,"grant_type",grant);add(f,"client_id",client);add(f,"resource",RESOURCE);if(code!=null)add(f,"code",code);if(verifier!=null)add(f,"code_verifier",verifier);if(redirect!=null)add(f,"redirect_uri",redirect);if(refresh!=null)add(f,"refresh_token",refresh);HttpURLConnection c=(HttpURLConnection)new URL(TOKEN).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");c.setRequestProperty("Accept","application/json");c.getOutputStream().write(f.toString().getBytes(StandardCharsets.UTF_8));int status=c.getResponseCode();String body=read(c,status>=400);if(status<200||status>=300){String detail="";try{JSONObject e=new JSONObject(body);detail=e.optString("error_description",e.optString("error",""));}catch(Exception ignored){}throw new Exception("Falha OAuth ("+status+")"+(detail.isEmpty()?"":": "+detail));}return new JSONObject(body);}
 private JSONObject verifyIdToken(String jwt,String client,String nonce)throws Exception{String[] p=jwt.split("\\.");if(p.length!=3)throw new Exception("ID token inválido.");JSONObject h=new JSONObject(new String(Base64.decode(p[0],Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING),StandardCharsets.UTF_8)),d=new JSONObject(new String(Base64.decode(p[1],Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING),StandardCharsets.UTF_8));if(!"RS256".equals(h.optString("alg"))||!"https://auth.openai.com".equals(d.optString("iss")))throw new Exception("Identidade do login inválida.");Object aud=d.opt("aud");boolean ok=client.equals(aud);if(aud instanceof JSONArray){ok=false;JSONArray a=(JSONArray)aud;for(int i=0;i<a.length();i++)if(client.equals(a.optString(i)))ok=true;}if(!ok||!nonce.equals(d.optString("nonce"))||d.optLong("exp",0)<System.currentTimeMillis()/1000L-5)throw new Exception("Identidade do login não confere.");HttpURLConnection c=(HttpURLConnection)new URL(JWKS).openConnection();JSONObject j=new JSONObject(read(c,false));JSONArray keys=j.getJSONArray("keys");JSONObject key=null;for(int i=0;i<keys.length();i++)if(h.optString("kid").equals(keys.getJSONObject(i).optString("kid")))key=keys.getJSONObject(i);if(key==null)throw new Exception("Chave de assinatura não encontrada.");BigInteger n=new BigInteger(1,Base64.decode(key.getString("n"),Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING)),e=new BigInteger(1,Base64.decode(key.getString("e"),Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING));PublicKey pk=KeyFactory.getInstance("RSA").generatePublic(new RSAPublicKeySpec(n,e));Signature sig=Signature.getInstance("SHA256withRSA");sig.initVerify(pk);sig.update((p[0]+"."+p[1]).getBytes(StandardCharsets.US_ASCII));if(!sig.verify(Base64.decode(p[2],Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING)))throw new Exception("Assinatura do login inválida.");return d;}
 private String hostId(){android.content.SharedPreferences p=context.getSharedPreferences(PREFS,Context.MODE_PRIVATE);String h=p.getString(HOST,null);if(h==null){h="urn:uuid:"+UUID.randomUUID();p.edit().putString(HOST,h).apply();}return h;}
 private JSONObject profile(){try{String s=secure.load();return s==null?null:new JSONObject(s);}catch(Exception e){return null;}}
 private void saveProfile(JSONObject p)throws Exception{secure.save(p.toString());}
 private static String random(int n){byte[] b=new byte[n];new SecureRandom().nextBytes(b);return b64url(b);}private static String b64url(byte[] b){return Base64.encodeToString(b,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
 private static void add(StringBuilder b,String k,String v)throws Exception{if(b.length()>0)b.append('&');b.append(URLEncoder.encode(k,"UTF-8")).append('=').append(URLEncoder.encode(v,"UTF-8"));}
 private static String read(HttpURLConnection c,boolean error)throws Exception{InputStream in=error?c.getErrorStream():c.getInputStream();if(in==null)return "";BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();String s;while((s=r.readLine())!=null)b.append(s);r.close();return b.toString();}
 private static Map<String,String> parseRequest(String line)throws Exception{Map<String,String> m=new HashMap<>();if(line==null)return m;String[] p=line.split(" ");if(p.length<2)return m;int q=p[1].indexOf('?');if(q<0)return m;for(String pair:p[1].substring(q+1).split("&")){String[] kv=pair.split("=",2);m.put(URLDecoder.decode(kv[0],"UTF-8"),URLDecoder.decode(kv.length>1?kv[1]:"","UTF-8"));}return m;}
 private static String safe(Throwable t){String s=t.getMessage();return s==null?t.getClass().getSimpleName():s;}
}
